#pragma once

#include <QHash>
#include <QString>

namespace fm {

// One FM27 role in one UI language, worded as the game words it.
struct RoleTerm {
    QString englishName;  // English role name the definitions use
    QString name;         // localized role name
    QString abbreviation; // localized abbreviation
};

// UI language ("de", "fr", "it", "zh_CN", "ru", "es") ->
// role id as in definitions_fm27.json ("IF", "CB-IP") -> term. English needs none.
// Generated by scripts/make_role_terms_fm27.py from the glossary.
const QHash<QString, QHash<QString, RoleTerm>> &fm27RoleTerms();

} // namespace fm
